from lib import *
S = SS('x85')
steps = [
    step("几种常见的启动失败,Boot 控制台上打印的报告,都是 Description 加 Action 两段,退出码都是 1。找不到依赖的 Bean:「Parameter 0 of constructor in demo.NeedsMissing required a bean of type 'demo.MissingDep' that could not be found.」,Action 是「Consider defining a bean of type 'demo.MissingDep' in your configuration.」。同类型有两个 Bean:Description 列出 dup1、dup2 各自定义在哪个 class 文件,Action 建议 @Primary、接收多个 Bean 或 @Qualifier。构造器循环依赖:画出 cycA ↔ cycB 的环,Action 说循环引用默认被禁止、应该消除依赖环,最后手段是设置属性自动打破环。@ConfigurationProperties 绑定失败(bp.port=abc):给出属性名、值、来源 systemProperties 和原因 NumberFormatException,Action 是「Update your application's configuration」。没配 url 的数据源:「Failed to configure a DataSource: 'url' attribute is not specified …」,Action 告诉你放一个内嵌数据库到 classpath,或者激活对应的 profile。端口被占用:「Web server failed to start. Port 53962 was already in use.」,Action 是停掉占用端口的进程或换端口。有一个没有报告的例子:@Value(\"${nope.value}\") 占位符没有值,控制台共 46 行、其中 32 行是堆栈帧,最里面的异常是 PlaceholderResolutionException: Could not resolve placeholder 'nope.value'——没有人给它写分析器。", t=tl(S(1)), mark=lidx(S(1), '@Value 占位符没有值', '没有失败报告'), done=lidx(S(1), '找不到依赖的 Bean', '同类型有两个 Bean', '构造器循环依赖', '绑定失败', '数据源', '端口被占用'), b=bars([['有失败报告的场景个数', 6, '6'], ['没有失败报告(只有堆栈)的场景个数', 1, '1'], ['没有报告的占位符场景的堆栈帧行数', 32, '32']], 32, done=[0], mark=[1, 2]), kv=KV([['报告格式', 'Description + Action,退出码 1'], ['找不到 Bean / 两个 Bean / 循环依赖', 'Action 直接给修复建议'], ['端口占用', 'Port 53962 was already in use'], ['占位符没有值', '没有分析器,就是 32 行堆栈']], ['占位符没有值'])),
    step("报告是怎么来的:FailureAnalyzer。扫描 classpath 上全部 jar 的 META-INF/spring.factories,登记在 FailureAnalyzer 名下的类一共 25 个,分布在 5 个 jar 里:spring-boot 18 个(如 ConfigDataNotFoundFailureAnalyzer、IncompatibleConfigurationFailureAnalyzer、NotConstructorBoundInjectionFailureAnalyzer)、spring-boot-autoconfigure 2 个(NoSuchBeanDefinitionFailureAnalyzer 等)、spring-boot-web-server 2 个(PortInUseFailureAnalyzer、MissingWebServerFactoryBeanFailureAnalyzer)、spring-boot-tomcat 1 个(ConnectorStartFailureAnalyzer)、spring-boot-jdbc 2 个(DataSourceBeanCreationFailureAnalyzer 等)。另外以 META-INF/spring/*.FailureAnalyzer.imports 形式的文件一个也没有,还是 spring.factories 一种登记方式。每个分析器拿到启动时抛出的异常,认得就返回一份 Description 加 Action,Boot 打印成报告;谁都不认得就退回到普通的错误日志和堆栈。", t=tl(S(2)), mark=lidx(S(2), 'spring-boot-4.0.8.jar', '另外'), done=lidx(S(2), '扫描 classpath', 'spring-boot-autoconfigure', 'spring-boot-web-server', 'spring-boot-tomcat', 'spring-boot-jdbc'), b=bars([['FailureAnalyzer 总数', 25, '25'], ['spring-boot 本体', 18, '18'], ['autoconfigure', 2, '2'], ['web-server', 2, '2'], ['jdbc', 2, '2'], ['tomcat', 1, '1']], 25, done=[0], mark=[1], cur=[2, 3, 4, 5]), kv=KV([['登记方式', 'META-INF/spring.factories,键是 FailureAnalyzer'], ['数量', '本 classpath 上共 25 个,5 个 jar'], ['认得', '返回 Description + Action'], ['不认得', '退回普通错误日志和堆栈']], ['登记方式'])),
    step("自己写一个。MyAnalyzer 继承 AbstractFailureAnalyzer<MyConfigException>,返回 new FailureAnalysis(描述, 建议, cause),在 META-INF/spring.factories 里登记。@PostConstruct 里抛 MyConfigException(\"缺少配置项 app.licence-key\"):控制台出现 APPLICATION FAILED TO START,Description 是「应用缺少必需的配置:缺少配置项 app.licence-key」,Action 是「在 application.properties 里加上这个配置项,或者设置对应的环境变量。」,退出码 1。再抛一个没有登记分析器的 OtherException(\"没人给我写分析器\"):没有失败报告,控制台 39 行、其中 25 行堆栈帧,最里面的异常是 demo.OtherException。也就是说「这个错误怎么修」可以直接写进启动失败的报告里。", t=tl(S(3)), mark=lidx(S(3), '没有登记分析器'), done=lidx(S(3), '登记了 MyAnalyzer', '应用缺少必需的配置', 'Action:'), b=bars([['有分析器:报告行数(数出来的)', 6, '6'], ['没有分析器:控制台行数', 39, '39'], ['没有分析器:堆栈帧行数', 25, '25']], 39, done=[0], mark=[1, 2]), kv=KV([['写分析器', 'extends AbstractFailureAnalyzer<异常类型>'], ['返回', 'new FailureAnalysis(描述, 建议, cause)'], ['登记', 'META-INF/spring.factories'], ['没有分析器', '39 行日志,25 行堆栈']], ['写分析器'])),
    step("同一个失败,用户看到的东西。找不到依赖的 Bean:默认控制台一共 18 行,其中失败报告 6 行、堆栈帧 0 行,其余是启动阶段的 INFO 日志;加 --debug 之后变成 404 行,堆栈帧有 24 行,而且出现了条件评估报告(CONDITIONS EVALUATION REPORT),最里面的异常是 NoSuchBeanDefinitionException: No qualifying bean of type 'demo.MissingDep' available。就是说默认看到的是整理过的报告,想看原始的异常链要加 --debug。", t=tl(S(4)), mark=lidx(S(4), '加 --debug 之后', 'NoSuchBeanDefinitionException'), done=lidx(S(4), '找不到依赖的 Bean:默认控制台'), b=bars([['默认控制台行数', 18, '18'], ['其中失败报告行数', 6, '6'], ['--debug 之后控制台行数', 404, '404'], ['--debug 之后的堆栈帧行数', 24, '24']], 404, done=[0, 1], mark=[2, 3]), kv=KV([['默认', '18 行,没有堆栈'], ['--debug', '404 行,带堆栈和条件评估报告'], ['想看根因', '--debug 或看报告里的 Description'], ['退出码', '1']], ['--debug'])),
]
A = mkartx('x85', 85, 'Spring,Boot,FailureAnalyzer,启动失败,诊断,真实验证,动画演示',
    '实测 Spring Boot 4.0.8 的启动失败报告:缺 Bean、两个 Bean、循环依赖、绑定失败、数据源、端口占用都有 Description 加 Action 的报告,占位符没有值却只有堆栈;classpath 上登记了 25 个 FailureAnalyzer;自己写一个并登记在 spring.factories 里就能得到自定义报告;--debug 之后控制台从 18 行变成 404 行。',
    '启动失败时那一段 APPLICATION FAILED TO START 是哪来的?为什么有的错误有修复建议、有的只有一大串堆栈?怎么给自己的错误也写一个?这篇把几种常见的启动失败都跑一遍,再自己写一个 FailureAnalyzer。',
    [('25 个', '本 classpath 上登记的 FailureAnalyzer 个数,分布在 5 个 jar'), ('Description + Action', '有分析器的启动失败都是这个格式,退出码 1'), ('39 行 / 25 行堆栈', '没有登记分析器的异常:控制台行数与其中的堆栈帧行数')],
    [('常见启动失败', '<p>缺 Bean、两个 Bean、循环依赖、绑定失败、数据源、端口占用都有报告;占位符没有值只有堆栈。</p>'),
     ('分析器从哪来', '<p>25 个 FailureAnalyzer 登记在 5 个 jar 的 spring.factories 里;认得就出报告,不认得退回堆栈。</p>'),
     ('自己写分析器', '<p>继承 AbstractFailureAnalyzer,返回 FailureAnalysis,在 spring.factories 里登记。</p>'),
     ('默认与 --debug', '<p>默认是整理过的 18 行,--debug 是 404 行并带堆栈和条件评估报告。</p>')],
    steps,
    [ENV_X + '。被测应用是 spring-boot-starter-webmvc、spring-boot-starter-jdbc 与 mysql-connector-j 的单个程序,用 Boot 默认的日志配置;每个失败场景一个独立 JVM,由属性 x85.case 开关对应的配置;报告取自进程输出里从 APPLICATION FAILED TO START 到 Action 段结束;分析器个数是从 classpath 全部 jar 的 META-INF/spring.factories 里数出来的(没有逐个实例化);端口占用场景用另一个进程以 IPv6 双栈方式占住端口(只占 127.0.0.1 时 Tomcat 照样启动成功)',
     '没有验证:其他 Boot 模块(Data、Security、Kafka 等)带来的 FailureAnalyzer;分析器之间的顺序与 @Order;MissingWebServerFactoryBeanFailureAnalyzer 等没有逐个触发的分析器;FailureAnalysisReporter 的扩展;日志框架不是 Logback 时的输出;原生镜像里的启动失败报告;为什么占位符没有值这种常见错误没有分析器(只观察到没有报告)'],
    'FailureAnalyzer')
